function countEven(num) {
  let count = 0;
  for (let x = 1; x <= num; x++) {
    let sum = 0;
    let rest = x;
    while (rest > 0) {
      sum += rest % 10;
      rest = Math.floor(rest / 10);
    }
    if (sum % 2 === 0) {
      count++;
    }
  }
  return count;
}

