function countEven(num) {
  const evens = [];
  for (let x = 1; x <= num; x++) {
    const digits = String(x).split('').map(Number);
    const total = digits.reduce((a, b) => a + b, 0);
    if (total % 2 === 0) evens.push(x);
  }
  return evens.length;
}

